    "rdsensBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "rdfamily",
                name = "rdsens",
                version = c(1,0,0),
                options = options,
                results = rdsensResults$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'auto')
        }))

#' RD Robustness Checks
#'
#' 
#' @param data .
#' @param outcome .
#' @param running .
#' @param treatment .
#' @param covs .
#' @param cluster .
#' @param cutVar .
#' @param cutoff .
#' @param p .
#' @param bwselect .
#' @param kernel .
#' @param vce .
#' @param level .
#' @param placeboCheck .
#' @param placeboFig .
#' @param placeboCuts .
#' @param bwCheck .
#' @param bwFig .
#' @param bwMult .
#' @param donutCheck .
#' @param donutFig .
#' @param donutRadii .
#' @param polyCheck .
#' @param polyFig .
#' @param polyOrders .
#' @param showHelp .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$placeboTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$placeboPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$bwTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$bwPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$donutTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$donutPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$polyTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$polyPlot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$placeboTable$asDF}
#'
#' \code{as.data.frame(results$placeboTable)}
#'
#' @export
rdsens <- function(
    data,
    outcome,
    running,
    treatment,
    covs,
    cluster,
    cutVar,
    cutoff = 0,
    p = 1,
    bwselect = "mserd",
    kernel = "triangular",
    vce = "nn",
    level = 95,
    placeboCheck = FALSE,
    placeboFig = FALSE,
    placeboCuts = "",
    bwCheck = FALSE,
    bwFig = FALSE,
    bwMult = "0.5,0.75,1,1.25,1.5,2",
    donutCheck = FALSE,
    donutFig = FALSE,
    donutRadii = "",
    polyCheck = FALSE,
    polyFig = FALSE,
    polyOrders = "1,2,3",
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("rdsens requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(running)) running <- jmvcore::resolveQuo(jmvcore::enquo(running))
    if ( ! missing(treatment)) treatment <- jmvcore::resolveQuo(jmvcore::enquo(treatment))
    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if ( ! missing(cluster)) cluster <- jmvcore::resolveQuo(jmvcore::enquo(cluster))
    if ( ! missing(cutVar)) cutVar <- jmvcore::resolveQuo(jmvcore::enquo(cutVar))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(running), running, NULL),
            `if`( ! missing(treatment), treatment, NULL),
            `if`( ! missing(covs), covs, NULL),
            `if`( ! missing(cluster), cluster, NULL),
            `if`( ! missing(cutVar), cutVar, NULL))


    options <- rdsensOptions$new(
        outcome = outcome,
        running = running,
        treatment = treatment,
        covs = covs,
        cluster = cluster,
        cutVar = cutVar,
        cutoff = cutoff,
        p = p,
        bwselect = bwselect,
        kernel = kernel,
        vce = vce,
        level = level,
        placeboCheck = placeboCheck,
        placeboFig = placeboFig,
        placeboCuts = placeboCuts,
        bwCheck = bwCheck,
        bwFig = bwFig,
        bwMult = bwMult,
        donutCheck = donutCheck,
        donutFig = donutFig,
        donutRadii = donutRadii,
        polyCheck = polyCheck,
        polyFig = polyFig,
        polyOrders = polyOrders,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- rdsensClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

